\begin{itemchoice}
			\itemch Số 5 là số có 1 chữ số, các số còn lại có 2 chữ số nên số 5 nhỏ nhất (Đúng).\
			\itemch Số 52 phải gồm có 5 chục và 2 đơn vị. Phát biểu nói ngược là Sai.\
			\itemch So sánh: $5 < 25 < 50 < 52 \Rightarrow$ Thứ tự sắp xếp từ bé đến lớn này là Đúng.\
			\itemch Số lớn nhất là 52, số nhỏ nhất là 5. Tổng bằng: $52 + 5 = 57$, phát biểu ra 55 là Sai.\
		\end{itemchoice}

\begin{itemchoice}
			\itemch Sách học sinh tiểu học dài khoảng hơn một gang tay rưỡi đến hai gang tay trẻ em (Đúng).\
			\itemch Số 20 gồm 2 chục, vậy thước kẻ dài 2 chục $\text{cm}$ (Đúng).\
			\itemch Cái tẩy chì của học sinh rất nhỏ, chỉ dài khoảng $3\text{ cm}$ đến $4\text{ cm}$. Dài $15\text{ cm}$ là gần bằng cái thước kẻ (Sai).\
			\itemch Theo chương trình học lớp 1 mới, học sinh đã biết $10\text{ cm} = 1\text{ dm}$ (Đúng).\
		\end{itemchoice}

\begin{itemchoice}
			\itemch Kẹo xanh là 35, kẹo đỏ là 21. Vì $35 > 21$ nên kẹo xanh nhiều hơn kẹo đỏ (Sai).\
			\itemch Tổng số kẹo: $35 + 21 = 56$ cái (Đúng).\
			\itemch Số kẹo xanh nhiều hơn đỏ là: $35 - 21 = 14$ cái (Đúng).\
			\itemch Ăn bớt 1 cái kẹo xanh thì còn $35 - 1 = 34$ cái. Số 34 có tận cùng là 4 nên không phải số tròn chục (Sai).\
		\end{itemchoice}

\begin{itemchoice}
			\itemch Thứ Ba liền sau Thứ Hai nên ngày 6 là Thứ Ba (Đúng).\
			\itemch Học sinh tiểu học chỉ đi học từ Thứ Hai đến Thứ Sáu (5 ngày), Thứ Bảy và Chủ Nhật được nghỉ (Sai).\
			\itemch Kim dài chỉ phút quay hết 1 vòng mất 1 tiếng, kim ngắn chỉ giờ quay hết 1 vòng mất 12 tiếng nên kim dài chạy nhanh hơn (Đúng).\
			\itemch Cả hai kim chập nhau ở số 12 là biểu thị mốc 12 giờ đúng (Đúng).\
		\end{itemchoice}
